#include "symrep_io.hpp"
#include <fstream>
using namespace symrep;
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("usage: galois output_directory max_weight");fs::path out(argv[1]);size_t maxw=std::stoul(argv[2]);std::array<std::string,5> names{"galois1a","galois1b","galois2a","galois2b","galois3"};std::vector<unsigned> bits(88),prev(8,0);for(size_t k=0;k<5;++k){auto a=read_matrix(out/"data"/(names[k]+".wxf"));for(size_t i=0;i<88;++i){require(a[i].nnz()==1&&a[i](0)==I(i),"Galois matrix not diagonal");if(a[i][0]==-1)bits[i]|=1<<k;}}std::ofstream report(out/"galois_dimensions.json");report<<"[\n";
for(size_t w=1;w<=maxw;++w){std::vector<unsigned> ch;if(w==1)ch=prev;else{auto t=read(out/("FEC_"+std::to_string(w)+".wxf"));ch.resize(t.dim(0));for(size_t row=0;row<t.dim(0);++row){bool first=true;for(size_t p=t.rowptr()[row];p<t.rowptr()[row+1];++p){auto i=t.index(p);unsigned c=prev[i[0]]^bits[i[1]];if(first){ch[row]=c;first=false;}else require(ch[row]==c,"Inhomogeneous Galois prefix");}require(!first,"Zero prefix row");}}
std::array<size_t,32> cnt{};for(auto c:ch)++cnt[c];for(size_t k=0;k<5;++k){Mat m(ch.size(),ch.size());for(size_t i=0;i<ch.size();++i)m[i].push_back(I(i),Q((ch[i]>>k&1)?-1:1));write(out/("galois"+std::to_string(k+1)+"_w"+std::to_string(w)+".wxf"),m);}if(w>1)report<<",\n";report<<"{\"physical_weight\":"<<w<<",\"dimension\":"<<ch.size()<<",\"characters\":{";bool first=true;for(size_t k=0;k<32;++k)if(cnt[k]){if(!first)report<<",";report<<"\""<<k<<"\":"<<cnt[k];first=false;}report<<"}}";report.flush();std::cout<<"Galois weight "<<w<<" dimension "<<ch.size()<<std::endl;prev=std::move(ch);}report<<"\n]\n";
}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}return 0;}
